{{ (function(){
 var kuvat = appsmith.store.tiskiKuvat || [];
 var tied = (tLiitteet.files || []);
 var CSS = "html,body{margin:0;height:100%;background:#FFFFFF;font-family:Inter,system-ui,sans-serif;overflow-y:auto}.rivi{display:flex;gap:12px;flex-wrap:wrap;padding:12px}.th{position:relative;width:118px;height:118px;border:1px solid #E3E5E8;border-radius:8px;overflow:hidden;background:#F9FAFB}.th img{width:100%;height:100%;object-fit:cover;display:block}.x{position:absolute;top:4px;right:4px;width:26px;height:26px;line-height:24px;text-align:center;border-radius:50%;background:rgba(17,24,39,.65);color:#fff;font-size:17px;cursor:pointer}.tyhja{padding:26px 16px;color:#6B7280;font-size:14px;text-align:center}.tied{padding:0 12px 12px;color:#374151;font-size:13px}";
 var JS = "document.addEventListener(\"click\",function(e){var x=e.target.closest(\".x\");if(x){parent.postMessage(\"poistaKuva:\"+x.getAttribute(\"data-i\")+\"|\"+Date.now(),\"*\");}});";
 var th = kuvat.map(function(k,i){ return '<div class="th"><img src="' + k.data + '"><span class="x" data-i="' + i + '">&times;</span></div>'; }).join("");
 if (!kuvat.length) { th = '<div class="tyhja">Ei viel\u00e4 kuvia. Paina &rdquo;Ota kuva tai piirr\u00e4&rdquo;.</div>'; }
 var lista = tied.length ? '<div class="tied">Muut liitteet: ' + tied.map(function(f){ return f.name; }).join(", ") + '</div>' : "";
 return '<html><head><meta charset="utf-8"><style>' + CSS + '</style></head><body><div class="rivi">' + th + '</div>' + lista + '<script>' + JS + '<\/script></body></html>';
})() }}
